(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x * 0.018 + t * 0.25) * 20 + Math.cos(y * 0.013 - t * 0.18) * 14;
  const w1y = Math.cos(y * 0.018 - t * 0.22) * 20 + Math.sin(x * 0.015 + t * 0.3) * 14;
  const sx = x + w1x, sy = y + w1y;
  const w2x = Math.sin(sx * 0.025 + t * 0.4) * 8 + Math.cos(sy * 0.02 - t * 0.35) * 6;
  const w2y = Math.cos(sy * 0.025 - t * 0.38) * 8 + Math.sin(sx * 0.022 + t * 0.42) * 6;
  const dx = sx + w2x, dy = sy + w2y;
  const src = [
    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.08, 2.0, 1.0],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.1, 1.7, 0.85],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.06, 2.3, 1.1],
    [120+Math.cos(t*0.8+1)*80, 180+Math.sin(t*0.6+3)*60, 0.12, 1.5, 0.9],
    [360+Math.sin(t*0.4+4)*90, 60+Math.cos(t*0.9+2)*70, 0.07, 2.6, 1.05],
    [240+Math.cos(t*0.35+5)*120, 200+Math.sin(t*0.55)*80, 0.09, 1.9, 0.95],
    [80+Math.sin(t*0.45+3)*110, 40+Math.cos(t*0.65)*55, 0.11, 2.1, 0.8],
    [400+Math.cos(t*0.55+2)*70, 200+Math.sin(t*0.75+1)*65, 0.065, 2.4, 1.15]
  ];
  let aS = 0, iS = 0, cross = 0;
  for (let i = 0; i < src.length; i++) {
    const [sX, sY, f, sp, wt] = src[i];
    const d = Math.sqrt((dx-sX)**2 + (dy-sY)**2);
    const wa = Math.sin(d*f - t*sp);
    const wi = Math.sin(d*f*0.7 + t*sp*0.6 + 1.5);
    aS += wa * wt;
    iS += wi * wt;
    for (let j = i + 1; j < src.length; j++) {
      const [sX2, sY2, f2, sp2] = src[j];
      const d2 = Math.sqrt((dx-sX2)**2 + (dy-sY2)**2);
      cross += Math.sin(d*f + d2*f2 - t*(sp+sp2)*0.5) * 0.15;
    }
  }
  const n = src.length;
  const act = aS/n, inh = iS/n, cr = cross/n;
  const bg1 = Math.sin(dx*0.04+dy*0.025+t*0.8);
  const bg2 = Math.sin(dx*0.03-dy*0.04+t*1.1);
  const bg3 = Math.sin((dx+dy)*0.12+t*2.5)*0.2;
  const bg4 = Math.sin((dx-dy)*0.1-t*2)*0.2;
  const bg5 = Math.sin(dx*0.07+t*1.5)*Math.cos(dy*0.06-t*1.2)*0.3;
  const bg = (bg1+bg2)/2 + bg3 + bg4 + bg5;
  const dist = Math.sqrt((dx-cx)**2 + (dy-cy)**2);
  const ang = Math.atan2(dy-cy, dx-cx);
  const sp1 = Math.sin(dist*0.05-ang*3-t*1.5);
  const sp2 = Math.sin(dist*0.04+ang*4-t*1.2);
  const sp3 = Math.sin(dist*0.08-ang*2+t*0.9)*0.3;
  const spiral = (sp1+sp2)*0.4 + sp3;
  const ripple = Math.sin(dist*0.1 - t*3)*Math.exp(-dist*0.008)*0.4;
  const lap = (act*2 - Math.sin((dx+2)*0.018+t*0.3)*0.5 - Math.sin((dx-2)*0.018+t*0.3)*0.5) * 0.3;
  const reaction = Math.tanh((act - inh*0.65 + bg*0.25 + spiral*0.8 + cr*0.6 + ripple + lap)*2.0);
  const cell1 = Math.sin(dx*0.15)*Math.sin(dy*0.15);
  const cell2 = Math.sin((dx+dy)*0.1+t)*0.5;
  const cell3 = Math.sin(dx*0.22-dy*0.18+t*0.7)*0.3;
  const cell = Math.tanh((cell1+cell2+cell3)*1.5)*0.25;
  const micro = Math.sin(dx*0.4+t*4)*Math.sin(dy*0.35-t*3.5)*0.08*Math.abs(reaction);
  const blend = reaction*0.65 + cell*0.2 + micro;
  const v = blend*0.5+0.5;
  const pal = [
    [6,12,52],[12,45,85],[18,85,115],[25,140,135],[55,175,145],
    [140,195,120],[210,200,75],[230,160,60],[225,110,65],[195,65,70],
    [150,40,75],[95,25,65],[45,18,55],[6,12,52]
  ];
  const idx = v*(pal.length-1), i = Math.min(idx|0, pal.length-2), f = idx-i;
  const c0 = pal[i], c1 = pal[i+1];
  const smooth = f*f*(3-2*f);
  const lum = 0.82 + Math.sin(reaction*Math.PI)*0.18;
  const edge = Math.abs(reaction) > 0.72 ? 1.18 : (Math.abs(reaction) > 0.5 ? 1.06 : 0.95);
  const glow = Math.max(0, 1 - dist*0.004)*0.12*Math.abs(reaction);
  return [
    Math.min(255, ((c0[0]+(c1[0]-c0[0])*smooth)*lum*edge + glow*180)|0),
    Math.min(255, ((c0[1]+(c1[1]-c0[1])*smooth)*lum*edge + glow*140)|0),
    Math.min(255, ((c0[2]+(c1[2]-c0[2])*smooth)*lum*edge + glow*200)|0)
  ];
}
